1	#!/usr/bin/env bash
2	# notes.sh add TEXT | list : a tiny notes CLI backed by notes.txt.
3	set -euo pipefail
4	FILE="${NOTES_FILE:-notes.txt}"
5	case "${1:-}" in
6	  add) shift; printf '%s\n' "$*" >> "$FILE" ;;
7	  list) [ -f "$FILE" ] && cat "$FILE" || true ;;
8	  *) echo "usage: notes.sh add TEXT | list" >&2; exit 64 ;;
9	esac
10

